"""Readable report of the conditional validation deletion assay; no model calls."""
import csv,hashlib,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def main():
    repo=Path(__file__).resolve().parents[1];root=repo/'results/motion_feature_deletion';status=json.loads((root/'status.json').read_text());job=status['job'];native=root/'native_completed';out=native/f'output/job_{job}'
    proof=json.loads((native/'transfer_integrity.json').read_text());assert proof['native_before_local_native_after_all_match'] and all(hashlib.sha256((native/k).read_bytes()).hexdigest()==v['sha256'] for k,v in proof['files'].items())
    s=json.loads((out/'summary.json').read_text());a=json.loads((out/'independent_audit.json').read_text());assert a['status']=='PASS' and json.loads((native/'execution_receipt.json').read_text())['status']=='COMPLETE_WITH_INDEPENDENT_AUDIT'
    with (out/'paired_deletion_constraint.csv').open() as f:paired=list(csv.DictReader(f))
    fig,axes=plt.subplots(1,2,figsize=(11.8,4.5),layout='constrained')
    absolute={}
    for ax,metric,title in zip(axes,['feature_mse','task_error'],['Complete feature error','Position error']):
        for j,arm in enumerate(['baseline','geometry_constraint']):
            means=[];lower=[];upper=[]
            for h in [3,6]:
                rr=[r for r in paired if r['arm']==arm and int(r['horizon'])==h];pairs=sorted({r['pair'] for r in rr});x=np.array([np.mean([float(r['uniform_'+metric]) for r in rr if r['pair']==p]) for p in pairs]);ix=np.random.default_rng(0).integers(0,96,(10000,96));lo,hi=np.percentile(x[ix].mean(1),[2.5,97.5]);means.append(x.mean());lower.append(x.mean()-lo);upper.append(hi-x.mean());absolute[arm,h,metric]=float(x.mean())
            bars=ax.bar([i+(j-.5)*.36 for i in range(2)],means,.36,color=['.75','.15'][j],edgecolor='black',label=['Frozen baseline','Geometry constraint'][j],yerr=[lower,upper],capsize=3);ax.bar_label(bars,fmt='%.4f',padding=20,fontsize=8)
        ax.set(xticks=[0,1],xticklabels=['3-step future','6-step future'],ylabel='MSE (lower is better)',title=title);ax.margins(y=.3);ax.legend(loc='upper center',bbox_to_anchor=(.5,-.13),ncol=2,fontsize=8)
    fig.suptitle('Same capacity, arbitrary retained observations\n96 validation pairs; six clock-only triples, every possible deletion retained',fontsize=12);fig.savefig(root/'deletion_generalization.png',dpi=180);plt.close(fig)
    counts={}
    for arm in ['baseline','geometry_constraint']:
        gains=s['summaries'][arm]['statistics']['oracle_baseline_comparisons'];transfer=[x for x in gains if x['choice']=='oracle_transfer'];counts[arm]={'both':sum(x['positive_both_metrics'] for x in transfer),'total':len(transfer)}
    text=['# Motion feature constraint: equal-capacity validation deletion','', '## What changed from the nominal two-frame check','', 'The preceding [feature-consistency experiment](MOTION_FEATURE_CONSTRAINT.md) improved the full visual prediction when given the prescribed informative pair of observations. This experiment tests the exact same fixed correction after arbitrary deletions. It does not choose the original informative frames by annotation or visibility.','', 'For each of the 96 original validation scene pairs, six unique triples are drawn using timestamps alone. All three deletion choices are evaluated. Every outcome retains exactly two past frames plus the same four recent frames and actions. Pools with no visible information remain included. The model and geometric correction receive only the retained frames, timestamps and legal actions. Visibility and original evidence labels are accessed only afterward for scoring and coverage.','', 'There is no training, fitting, encoder run, policy optimization, held-out test forward or fresh9137 access. All three frozen models and horizons 3/6 are retained. The strength-1 correction and its frozen feature/readout matrices are byte-identical to the preceding feasibility experiment.','', '![Deletion generalization](../results/motion_feature_deletion/deletion_generalization.png)','', 'Each bar averages every deletion choice in every pool, then siblings and seeds within each of 96 independent base pairs. Error bars are 95% paired-basepair bootstrap intervals, 10,000 draws, seed 0. These are complete visual-feature and position errors, not classification accuracies.','', '| Arm | Feature error h3 | Feature error h6 | Position error h3 | Position error h6 |','|---|---:|---:|---:|---:|']
    for arm in ['baseline','geometry_constraint']:
        text.append('|'+arm+'|'+'|'.join(f'{absolute[arm,h,m]:.7f}' for m,h in [('feature_mse',3),('feature_mse',6),('task_error',3),('task_error',6)])+'|')
    text+=['','## Does the deletion ranking transfer across horizons?','', 'A diagnostic oracle chooses which item to delete using prediction-feature error at one future horizon, then evaluates that choice at the other horizon. Compare its feature and task errors with uniform deletion, FIFO and reject-newest. Positive paired lower bounds in both errors indicate cross-horizon agreement in this diagnostic. **The choice uses future scoring targets and is not a deployable or learned retention policy.**','', '| Arm | Positive feature-and-task comparisons | Against each baseline |','|---|---:|---|']
    for arm in ['baseline','geometry_constraint']:
        transfer=[x for x in s['summaries'][arm]['statistics']['oracle_baseline_comparisons'] if x['choice']=='oracle_transfer'];per={b:sum(x['positive_both_metrics'] for x in transfer if x['baseline']==b) for b in ['uniform','fifo','reject']};text.append(f'|{arm}|{counts[arm]["both"]}/{counts[arm]["total"]}|uniform {per["uniform"]}/8; FIFO {per["fifo"]}/8; reject-newest {per["reject"]}/8|')
    text+=['', 'The 24 comparisons per arm are two evaluation horizons × three baselines × three seed estimates plus their mean. They share the same 96 base pairs and are not 24 independent datasets. These descriptive checks do not replace original Motion acceptance.','', '## Paired oracle effects, mean over seeds','', 'Positive percentage means less error than the named simple deletion baseline. Each choice uses the opposite future horizon, so these are future-informed diagnostic upper bounds.','', '| Arm | Evaluated horizon | Baseline | Feature reduction | Position reduction | Positive CI in both? |','|---|---:|---|---:|---:|---|']
    for arm in ['baseline','geometry_constraint']:
        for x in s['summaries'][arm]['statistics']['oracle_baseline_comparisons']:
            if x['choice']!='oracle_transfer' or x['seed']!='mean':continue
            values=[x['metrics'][k]['relative_gain'] for k in ['feature_mse','task_error']];text.append('|'+arm+f'|{x["horizon"]}|{x["baseline"]}|'+'|'.join('undefined (floor)' if v is None else f'{100*v:.2f}%' for v in values)+f'|{x["positive_both_metrics"]}|')
    local=json.loads((root/'local_statistics_review.json').read_text())
    visibility=json.loads((out/'retained_visibility_diagnosis.json').read_text())
    text+=['','## Generalization failure despite positive ranking diagnostics','', 'The correction is not ready to replace the Motion predictor. It improves nominal predictions when the prescribed observations show real motion, but worsens average prediction over arbitrary retained sets. The cross-horizon oracle counts remain 24/24 for both arms; these positive ranking diagnostics do not establish that the corrected predictor itself is accurate or robust.','', 'The following matched-arm comparison is a posthoc explanation, not a new acceptance rule. Every pair and pool remains included. Positive percentages in this table mean **more error after correction**.','', '| Horizon | Error | Relative error increase [paired95%CI] |','|---|---|---:|']
    for x in local['additional_matched_arm_effects']:text.append(f'|{x["horizon"]}|{x["metric"]}|{-100*x["relative_improvement"]:.2f}% [{-100*x["high"]:.2f}, {-100*x["low"]:.2f}]|')
    text+=['', '## Where the error concentrates','', 'Visibility is scoring-only here. The table is a posthoc association, not an isolated causal test: groups differ in retained contents and timestamps. No group was filtered or used to activate/deactivate the normal correction.','', '| Retained visible frames | h6 outcome rows per arm | Feature MSE baseline / correction | Position MSE baseline / correction |','|---|---:|---:|---:|']
    for x in visibility['groups']:
        if x['horizon']!=6:continue
        b=x['means']['baseline'];g=x['means']['geometry_constraint'];text.append(f'|{x["retained_visible_count"]}/2|{x["rows_per_arm"]:,}|{b["feature_mse"]:.6f} / {g["feature_mse"]:.6f}|{b["task_error"]:.6f} / {g["task_error"]:.6f}|')
    text+=['', 'The largest regression occurs when one retained frame contains visible motion and the other contains the shutter. The current geometric formula treats the difference between their decoded positions as physical displacement. This association and the formula identify a plausible input-validity failure; they do not prove a unique cause of the original predictor deficit. A successful experiment using two known visible evidence frames could not establish this robustness.','', 'Next bounded design, not executed: test an observed-content reliability guard before applying geometric extrapolation, using only retained/current features. Such a guard must never consult simulator visibility, evidence-importance labels or future targets. It is an inference-quality check, not learned retention-policy training. Any exact-equality cue in this synthetic renderer would also need disclosure as simulator-specific. Preserve all original gates and retain all failed/uninformative cases. Do not adopt the unconditional correction or retune it on held-out test data.','', '## Verification and conclusion boundary','', f'The run produced {s["raw_rows"]:,} scalar rows, {s["witness_vectors"]:,} full baseline vectors and {s["paired_rows"]:,} compact paired rows. Every vector-derived feature and position error was independently recomputed using QR/SVD projection and a separate reflection implementation. The raw fork/pool/capacity axes and all {a["independent_scalar_statistics"]} statistics were independently reconstructed; the same 192 intervals were then reproduced locally from compact paired data. Maximum scalar discrepancy {a["feature_and_position_max_difference"]:.3g}. Compact before/local/after transfer hashes match; vectors and large raw CSV remain HPC.','', 'This is a validation-only generalization check for one fixed correction. It does not establish performance on original long-gap/distractor tests, independent confirmation, policy learnability or Phase1_GO. The original full-test Motion counts remain 35/51 and 8/32 fixed-reference until a separately locked full re-evaluation. Gate remains its separately supported development candidate. New GPU cost is zero; remaining cumulative budget is 16,077 seconds. This is an I-JEPA prototype, not direct V-JEPA validation. No GitHub update.']
    (repo/'docs/MOTION_FEATURE_DELETION.md').write_text('\n'.join(text)+'\n');print(json.dumps({'cross_horizon_comparisons':counts,'absolute_means':{str(k):v for k,v in absolute.items()}}))

if __name__=='__main__':main()
